// R_NilValue — the NULL singleton (NILSXP, type=0, length=0, data=NULL).
//
// Real declaration in Rinternals.h line 412:
//   LibExtern SEXP R_NilValue;    /* The nil object */
//
// The primary definition lives in SEXP.h under FAKE_R_NILVALUE_DEFINED.
// The block below is a guarded fallback definition for the case where
// this header is included into a translation unit without SEXP.h having
// been included first.
//
// Implementation mechanism: a function-local static SEXPREC (guaranteed
// to be initialized exactly once by the C++ runtime, before first use,
// regardless of static-initialization order across translation units).
// A module-level `static SEXP R_NilValue` stores the resulting pointer.
//
// Observable properties (consistent with the real R runtime):
//   TYPEOF(R_NilValue)  == NILSXP  (0)
//   LENGTH(R_NilValue)  == 0
//   isNull(R_NilValue)  == 1 (true — s->type == NILSXP)
//   R_NilValue          != nullptr (safe to dereference in TYPEOF / isNull)
//
// Usage patterns satisfied:
//   P1 (rpart.c:64):
//     SEXP csplit3 = R_NilValue;   // pointer assignment — SEXP = SEXP, OK
//   P2 (rpart_callback.c:71):
//     return R_NilValue;            // returning a SEXP from SEXP function, OK
