#ifndef FAKE_R_NILVALUE_DEFINED
#define FAKE_R_NILVALUE_DEFINED

inline SEXP make_nil_value() {
    static SEXPREC nil_rec = { NILSXP, 0, 0, 0, NULL };
    return &nil_rec;
}

/* Every translation unit that includes this header gets its own static
   SEXP R_NilValue variable; all point to the same SEXPREC because
   make_nil_value() uses a function-local static (initialized once). */
static SEXP R_NilValue = make_nil_value();

#endif // FAKE_R_NILVALUE_DEFINED

