// Rf_error — [[noreturn]] variadic function that formats a message and
// throws RError (Invariant 1: C++ exception-based error signalling).
//
// Guarded fallback definition for translation units that include this
// header without having already pulled in the Rf_error definition from
// another fake header.  The primary definition is expected in a dedicated
// error/warning fake header (Category D); this fallback ensures that the
// error_return macro compiles even when that header is absent.
//
// The real Rinternals.h declares:
//   void Rf_error(const char *, ...);   // line in R_ext/Error.h
// and aliases it:
//   #define error Rf_error              // in Rinternals.h
//
// In the fake, Rf_error throws RError so that C++ callers (and .Call-entry
// wrappers) can catch it at the boundary rather than relying on longjmp.
// ---------------------------------------------------------------------------
#ifndef FAKE_RF_ERROR_DEFINED
#define FAKE_RF_ERROR_DEFINED

[[noreturn]] inline void Rf_error(const char *fmt, ...) {
    char buf[1024];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    throw RError(buf);
}

#ifndef error
#define error Rf_error
#endif

#endif // FAKE_RF_ERROR_DEFINED

